END $seed$;
COMMIT;
SELECT jsonb_build_object('test_drafts',(SELECT count(*) FROM private.products WHERE product_code LIKE 'TEST-CLOUD-20261022-%'),
 'real_price_records',(SELECT count(*) FROM private.offer_prices pr JOIN private.product_offers o ON o.id=pr.offer_id
   JOIN private.products p ON p.id=o.product_id WHERE p.product_code LIKE 'TEST-CLOUD-20261022-%'),
 'public_test_products',(SELECT count(*) FROM private.products WHERE product_code LIKE 'TEST-CLOUD-20261022-%' AND publication_status='published')) AS fixture_status;
